export const DEFAULT_PAGE_SIZE = 20;
export const MAX_PAGE_SIZE = 100;
export const DEFAULT_PAGE = 1;

export interface PaginationParams {
    limit?: number;
    cursor?: string;
}

export type IPaginationParams = PaginationParams;

export interface OffsetPaginationParams {
    limit?: number;
    offset?: number;
    page?: number;
}

export interface PaginatedResult<T> {
    items: T[];
    pagination: {
        page: number;
        page_size: number;
        total: number;
        total_pages: number;
        has_next?: boolean;
        next_cursor?: string;
    };
}

export interface CursorPaginatedResult<T> {
    items: T[];
    pagination: {
        has_next: boolean;
        next_cursor?: string;
        total?: number;
    };
}

export function validatePagination(params?: PaginationParams): PaginationParams {
    if (!params) return { limit: DEFAULT_PAGE_SIZE };

    return {
        limit: Math.min(Math.max(1, params.limit ?? DEFAULT_PAGE_SIZE), MAX_PAGE_SIZE),
        cursor: params.cursor,
    };
}

export function validateOffsetPagination(params?: OffsetPaginationParams): OffsetPaginationParams {
    if (!params) return { limit: DEFAULT_PAGE_SIZE, page: DEFAULT_PAGE };

    return {
        limit: Math.min(Math.max(1, params.limit ?? DEFAULT_PAGE_SIZE), MAX_PAGE_SIZE),
        offset: params.offset,
        page: Math.max(1, params.page ?? DEFAULT_PAGE),
    };
}

export function buildPaginationQuery(params?: PaginationParams): Record<string, string> {
    const validated = validatePagination(params);
    const query: Record<string, string> = {};
    const limit = validated.limit ?? DEFAULT_PAGE_SIZE;

    if (limit !== DEFAULT_PAGE_SIZE) {
        query.limit = limit.toString();
    }

    if (validated.cursor) {
        query.cursor = validated.cursor;
    }

    return query;
}

export function buildOffsetPaginationQuery(params?: OffsetPaginationParams): Record<string, string> {
    const validated = validateOffsetPagination(params);
    const query: Record<string, string> = {};
    const limit = validated.limit ?? DEFAULT_PAGE_SIZE;
    const page = validated.page ?? DEFAULT_PAGE;

    if (limit !== DEFAULT_PAGE_SIZE) {
        query.limit = limit.toString();
    }

    if (validated.offset !== undefined) {
        query.offset = validated.offset.toString();
    }

    if (page !== DEFAULT_PAGE) {
        query.page = page.toString();
    }

    return query;
}

export function createPaginatedResult<T>(
    items: T[],
    page: number,
    pageSize: number,
    total: number,
): PaginatedResult<T> {
    const totalPages = Math.ceil(total / pageSize);

    return {
        items,
        pagination: {
            page,
            page_size: pageSize,
            total,
            total_pages: totalPages,
            has_next: page < totalPages,
        },
    };
}

export function createCursorPaginatedResult<T>(
    items: T[],
    hasNext: boolean,
    nextCursor?: string,
    total?: number,
): CursorPaginatedResult<T> {
    return {
        items,
        pagination: {
            has_next: hasNext,
            next_cursor: nextCursor,
            total,
        },
    };
}

export function calculateOffset(page: number, pageSize: number): number {
    return (Math.max(1, page) - 1) * Math.min(pageSize, MAX_PAGE_SIZE);
}
